#include <bits/stdc++.h>
#define pair_int pair<int,int>
#define reset_array(a,x) memset(a,x,sizeof(a))
#define make_pair std::make_pair
#define get_first first
#define get_second second
using namespace std;
typedef long long ll_type;
typedef unsigned long long ull_type;
typedef unsigned int uint_type;
typedef long double ld_type;
const int MAXN=55, MAXT=2*MAXN, MAXP=MAXT*MAXN, MAXE=5*MAXT*MAXN*MAXN;
const int INF=1e9;

inline char read_char(){
	return getchar();
	static const int buf_size=1<<16; static char buf[buf_size],*p=buf,*q=buf;
    return p==q&&(q=(p=buf)+fread(buf,1,buf_size,stdin),p==q)?EOF:*p++;
}
inline long long read_ll(){
    long long x=0; char c=read_char(); bool neg=false;
    while(c<'0'||c>'9'){if(c=='-') neg=true;c=read_char();}
    while(c>='0'&&c<='9') x=(x<<1)+(x<<3)+c-'0',c=read_char();
    return neg?(~x+1):x;
}

struct Edge{
	int to,bottom,length,ne;
}edge_list[MAXE];
int edge_idx=1,head[MAXP];
int N,M,K,C,D,cnt[MAXN];
int node_id[MAXN][MAXT],S=1,E=2,pt=2;
bool in_queue[MAXP];
int dist[MAXP],total_cost;
queue<int> q;

inline void add_edge(int a,int b,int c,int l){
	edge_list[++edge_idx].to=b; edge_list[edge_idx].ne=head[a]; head[a]=edge_idx;
	edge_list[edge_idx].length=c; edge_list[edge_idx].bottom=l;
}

inline void add_bi_edge(int a,int b,int c,int l){
	add_edge(a,b,c,l);
	add_edge(b,a,-c,0);
}

inline bool bellman_ford(){
	for(int i=1;i<=pt;i++) in_queue[i]=false,dist[i]=INF;
	dist[S]=0; q.push(S);
	while(!q.empty()){
		int p=q.front(); q.pop();
		in_queue[p]=false;
		for(int i=head[p];i;i=edge_list[i].ne){
			if(!edge_list[i].bottom) continue;
			int b=edge_list[i].to;
			if(dist[b]>dist[p]+edge_list[i].length){
				dist[b]=dist[p]+edge_list[i].length;
				if(!in_queue[b]) q.push(b), in_queue[b]=true;
			}
		}
	}
	return dist[E]<INF;
}

int max_flow(int x,int flow){
	if(x==S) return flow;
	in_queue[x]=true;
	int remaining=flow;
	for(int i=head[x];i;i=edge_list[i].ne){
		int b=edge_list[i].to;
		if(in_queue[b]||!edge_list[i^1].bottom||dist[x]<dist[b]+edge_list[i^1].length) continue;
		int pushed=max_flow(b,min(remaining,edge_list[i^1].bottom));
		if(pushed){
			remaining-=pushed;
			edge_list[i^1].bottom-=pushed;
			edge_list[i].bottom+=pushed;
			if(!remaining) break;
		}
	}
	return flow-remaining;
}

int main(){
    N=read_ll(); M=read_ll(); K=read_ll(); C=read_ll(); D=read_ll();
    for(int i=1;i<=K;i++) cnt[read_ll()]++;
    for(int i=1;i<=N;i++){
    	for(int j=1;j<=K+M+2;j++){
    		node_id[i][j]=++pt;
    		if(i==1) add_edge(node_id[i][j],E,C*(j-1),INF);
    		if(j>1) add_edge(node_id[i][j-1],node_id[i][j],0,INF);
    	}
    	if(cnt[i]) add_edge(S,node_id[i][1],0,cnt[i]);
    }
    for(int i=1;i<=M;i++){
    	int a=read_ll(),b=read_ll();
    	for(int j=1;j<=K+M+1;j++){
    		for(int k=1;k<=2*K-1;k+=2){
    			add_edge(node_id[a][j],node_id[b][j+1],k*D,1);
    			add_edge(node_id[b][j],node_id[a][j+1],k*D,1);
    		}
    	}
    }
    int total_flow=0;
    while(bellman_ford()){
    	int flow_value=-1;
    	while(flow_value){
    		reset_array(in_queue,0);
    		flow_value=max_flow(E,INF);
    		total_flow+=flow_value;
    		total_cost+=dist[E]*flow_value;
    	}
    }
    assert(total_flow==K);
	printf("%d\n",total_cost);
    return 0;
}
